#!/usr/bin/env python3
"""
Round 214o (culprits), 15 October 2026. Needs round 213o.

Planets on in the Sun view; Sunlight's reach retitled, with search and the
worlds that could hold life; gravity reaching Earth to Antigravity; the sky
chart with axes, lines and names; gravity's fabric beyond the Milky Way, raised.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 214o (15 October)\n\nNeeds round 213o (guards on its heading). Tiles patch round214o_tiles.py\n(culprits-tiles-more), then refresh gem_solar and reach. No app.js?v= bump;\nbodies.html is asked for as ?v=214.\n\n- Sun view: the planets row on from the start; "what people have sent into\n  orbit around it".\n- Sunlight\'s reach retitled "Sunlight\'s reach – where else the Sun could be\n  parasitized, now or then". A search box (every view): finds a mark, star,\n  galaxy or place name among the ticked rows, goes to it and opens its box.\n  A new row, Worlds that could hold life (reach/life.json: every row of\n  Wikipedia\'s List of potentially habitable exoplanets and List of ocean\n  worlds), and a View choice "Only worlds that could hold life".\n- Sky view: gravity reaching Earth taken out (now row pullin in From Earth,\n  placed by direction and distance; layer earth_pull_in under Antigravity);\n  heading "light reaching Earth from everything with a published\n  brightness". The chart gets a grid with hours and degrees along the edges,\n  the celestial equator, ecliptic and plane of the Milky Way, the 88\n  constellations named at the middle of their stars (HYG con), the brightest\n  named stars; fainter stars and deep-sky objects smaller and dimmer. The\n  globe gets the constellation names and the three lines.\n- Gravity\'s fabric: adds every Wikidata item with a mass, distance and place\n  (reach/masses.json), deduplicated against the bodies already there; a\n  raised, terraced surface (one step per field, lifted by the summed pull),\n  lit from the upper left.\n- Panel: Solar Tech = light reaching Earth, Sunlight\'s reach, solar farms,\n  solar panel makers. Antigravity = gravity\'s fabric, anti-gravity, gravity\n  reaching Earth. To Earth\'s heading is "Earth\'s gravity reach".\n- Solar farms note: far zooms carry a few columns, close zooms every column\n  (gem_solar.py now builds two tiers; it was over GitHub\'s 100 MB).\n\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round214o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 213o" not in h.read_text(encoding="utf-8"):
        sys.exit("round214o: round 213o must be applied first (round213o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round214o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/bodies.html", "map/test.mjs", check=False)
            sys.exit("round214o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round214o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
